import { describe, it } from 'vitest'
import {
  stepSimulation,
  iterateBuildings,
  getObjectiveStatus,
  getProgression,
  type SimulationConfig,
  type SimulationState,
  type BuildingType,
} from '@/index'
import { findScenario, createScenarioState } from '../src/application/scenarios.js'

const config: SimulationConfig = { world: { seed: 'dbg', width: 24, height: 8 } }

const place = (
  state: SimulationState,
  type: BuildingType,
  x: number,
  y: number
): SimulationState => {
  let next = state
  for (let attempt = 0; attempt < 200; attempt += 1) {
    const before = Object.keys(next.buildings).length
    next = stepSimulation(next, { type: 'placeBuilding', x, y, buildingType: type })
    if (Object.keys(next.buildings).length > before) return next
  }
  return next
}

describe('debug', () => {
  it('prints blockers', () => {
    const definition = findScenario('water-reserve-industry')
    if (definition === undefined) throw new Error('missing')
    let state = createScenarioState(config, definition)
    state = place(state, 'workshop', 4, 2)
    for (let i = 0; i < 3; i += 1) state = stepSimulation(state)
    const workshopId = [...iterateBuildings(state)].find((b) => b.type === 'workshop')?.id
    const wellId = [...iterateBuildings(state)].find((b) => b.type === 'well')?.id
    const worker = Object.values(state.colonists).find((c) => c.workplaceId === wellId)
    if (workshopId === undefined || worker === undefined) throw new Error('setup')
    state = stepSimulation(state, { type: 'reassignColonist', colonistId: worker.id, workplaceId: workshopId })
    let ticks = 0
    while (state.resources.water > 0 && ticks < 60) { state = stepSimulation(state); ticks += 1 }
    state = place(state, 'well', 2, 2)
    for (let i = 0; i < 3; i += 1) state = stepSimulation(state)
    state = stepSimulation(state, { type: 'reassignColonist', colonistId: worker.id, workplaceId: wellId! })
    for (let i = 0; i < 5; i += 1) state = stepSimulation(state)
    const status = getObjectiveStatus(state, definition.objective)
    console.log('TICK', state.time.tick, 'MONEY', state.resources.money)
    console.log('STATUS', JSON.stringify(status))
    console.log('STAGE', getProgression(state).stage)
    console.log('BUILDINGS', Object.values(state.buildings).map((b) => `${b.type}@${b.x},${b.y}:${b.status}`).join(' '))
  })
})

