/** Step until the treasury covers a 25-cost build (Step001: money only —
 * there is no stored-production figure; the domain's same-tick revenue clause
 * is the only relief, and these fixtures keep a rest buffer instead). */
async function stepUntilPlaceable(page, cost = 25, maxTicks = 60) {
  for (let i = 0; i < maxTicks; i += 1) {
    const s = await stats(page);
    if (Number(s.money) >= cost) return s;
    await step(page);
  }
  throw new Error(`treasury never reached ${cost}: ${JSON.stringify(await stats(page))}`);
}

