import type { BuildingStatus, BuildingType } from '../building/building.js'
import { iterateBuildings, iterateColonists } from '../housing/housing.js'
import type { ColonistState } from '../population/colonist.js'
import type { SimulationState } from '../simulation/state.js'

/** Jobs offered by one operational Workshop (Step 07C §3: capacity = 1). */
export const WORKSHOP_JOB_CAPACITY = 1

/**
 * The only building facts a workplace decision needs. Structural so that both
 * canonical `BuildingState` and the derived `BuildingInspection` qualify.
 */
export interface WorkplaceLike {
  readonly type: BuildingType
  readonly status: BuildingStatus
}

/** Jobs offered by one operational Farm (Step 10E: capacity = 1, like Workshops). */
export const FARM_JOB_CAPACITY = 1

/** An operational Farm offers jobs (Step 10E). Same lifecycle rule as Workshops. */
export const isOperationalFarm = (building: WorkplaceLike): boolean =>
  building.type === 'farm' && building.status === 'operational'

/**
 * An operational Well offers jobs (Step 10P). Same lifecycle rule as every
 * other workplace; it is a concrete type, not a generic producer.
 */
export const isOperationalWell = (building: WorkplaceLike): boolean =>
  building.type === 'well' && building.status === 'operational'

/** A building offers jobs once operational: Farm, Workshop or Well (Step 10P). */
export const isOperationalWorkplace = (building: WorkplaceLike): boolean =>
  isOperationalWorkshop(building) ||
  isOperationalFarm(building) ||
  isOperationalWell(building)

/** A workplace only offers jobs once operational (docs/06 lifecycle). */
export const isOperationalWorkshop = (building: WorkplaceLike): boolean =>
  building.type === 'workshop' && building.status === 'operational'

/** Jobs offered by one building: 1 for an operational Farm or Workshop, else 0. */
export const jobCapacityOf = (building: WorkplaceLike): number =>
  isOperationalWorkplace(building) ? WORKSHOP_JOB_CAPACITY : 0

/** Total job capacity of the colony: operational Farms + Workshops × capacity. */
export const getJobCapacity = (state: SimulationState): number => {
  let capacity = 0
  for (const building of iterateBuildings(state)) {
    capacity += jobCapacityOf(building)
  }
  return capacity
}

/**
 * A colonist is employed iff `workplaceId` resolves to an operational Farm
 * or Workshop (Step 10E: Farms joined the workplace pool). Resolving the
 * reference keeps "non-operational workplace => zero valid workers" true.
 */
export const isEmployed = (
  state: SimulationState,
  colonist: ColonistState
): boolean => {
  const workplaceId = colonist.workplaceId
  if (workplaceId === null) {
    return false
  }
  const workplace = state.buildings[workplaceId]
  return workplace !== undefined && isOperationalWorkplace(workplace)
}

/** Employed colonists — the deterministic labor supply of this tick. */
export const countEmployedWorkers = (state: SimulationState): number => {
  let count = 0
  for (const colonist of iterateColonists(state)) {
    if (isEmployed(state, colonist)) {
      count += 1
    }
  }
  return count
}

/** Colonists working at one specific building (used by inspection/tests). */
export const countWorkersAt = (
  state: SimulationState,

interface EntityCounters {
  readonly nextBuildingId: number
  readonly nextColonistId: number
  readonly nextRoadId: number
}

export interface SimulationState {
  readonly config: SimulationConfig
  readonly time: SimulationTime
  readonly resources: ResourceStock
  /** Centralized storage hub (Step 10BG). Aggregates surplus production
   * for strategic buffering. */
  readonly storage: StorageHub
  readonly buildings: Readonly<Record<string, BuildingState>>
  readonly colonists: Readonly<Record<string, ColonistState>>
  /** Authoritative mobility infrastructure (Step 09C). Derived road
   * connectivity is never stored here. */
  readonly roads: Readonly<Record<string, RoadState>>
  readonly counters: EntityCounters
}

/**
 * Deterministic configuration required to reproduce behavior
 * (docs/30-architecture-foundation.md, canonical state contents).
 */
export interface SimulationConfig {
  readonly world: WorldConfig
}

/**
 * Canonical world normalization (Step 10AV). Terrain is stored in exactly one
 * form: validated keys, deduplicated, sorted by (x, y). An EMPTY list is
 * dropped so "no terrain" has a single representation (the absent field) and
 * a terrain-free world keeps its historical canonical form and hash. A
 * malformed key throws here, at the only place a world is constructed.
 */
export const normalizeWorldConfig = (world: WorldConfig): WorldConfig => {
  const blocked = world.blockedCells
  if (blocked === undefined) {
    return world
  }
  const normalized = normalizeBlockedCells(blocked)
  if (normalized.length === 0) {
    return { seed: world.seed, width: world.width, height: world.height }
  }
  return { ...world, blockedCells: normalized }
}

/** The same normalization applied to a whole simulation config. */
export const normalizeConfig = (config: SimulationConfig): SimulationConfig => {
  const world = normalizeWorldConfig(config.world)
  return world === config.world ? config : { world }
}

export const createInitialState = (config: SimulationConfig): SimulationState => {
  const normalized = normalizeConfig(config)
  assertValidConfig(normalized)
  return {
    config: normalized,
    time: { tick: 0 },
    resources: createInitialResourceStock(),
    storage: createInitialStorageHub(),
    buildings: {},
    colonists: {},
    roads: {},
    counters: { nextBuildingId: 1, nextColonistId: 1, nextRoadId: 1 },
  }
}
====HASH
/**
 * Deterministic canonical serialization + hashing (docs/22, docs/31).
 *
 * - canonicalJson: stable key ordering, no locale/format drift.
 * - hash: FNV-1a 64-bit (BigInt), printed as fixed-width hex.
 *
 * Adding a simulation-critical field automatically changes the hash; that
 * is intended (schema change => save version bump, docs/22 migration rule).
 */

import type { SimulationState } from './state.js'

const isPlainObject = (value: unknown): value is Record<string, unknown> =>
  typeof value === 'object' && value !== null && !Array.isArray(value)

/** Stable serialization: object keys sorted, arrays kept in order. */
export const canonicalJson = (value: unknown): string => {
  if (value === null) return 'null'
  switch (typeof value) {
    case 'string':
      return JSON.stringify(value)
    case 'number':
      return Number.isFinite(value)
        ? JSON.stringify(value)
        : (() => { throw new Error(`Non-finite number not canonical: ${value}`) })()
    case 'boolean':
      return value ? 'true' : 'false'
    case 'object':
      break
    default:
      throw new Error(`Value not canonically serializable: ${String(value)}`)
  }
  if (Array.isArray(value)) {
    return `[${value.map(canonicalJson).join(',')}]`
  }
  if (isPlainObject(value)) {
    const entries = Object.keys(value)
      .sort()
      .map((key) => `${JSON.stringify(key)}:${canonicalJson(value[key])}`)
    return `{${entries.join(',')}}`
  }
  throw new Error(`Value not canonically serializable: ${String(value)}`)
}

/** FNV-1a 64-bit over UTF-16 code units of the string. Pure, deterministic, environment-independent. */
export const fnv1a64 = (input: string): string => {
  const prime = 0x100000001b3n
  let hash = 0xcbf29ce484222325n
  for (let i = 0; i < input.length; i++) {
    hash ^= BigInt(input.charCodeAt(i))
    hash = (hash * prime) & 0xffffffffffffffffn
  }
  return hash.toString(16).padStart(16, '0')
}

/** Canonical JSON of the full canonical state. */
export const serializeCanonicalState = (
  state: SimulationState
): string => canonicalJson(state)

/** Deterministic canonical state hash. Same state => same hash. */
export const hashCanonicalState = (state: SimulationState): string =>
  fnv1a64(serializeCanonicalState(state))

