    const line = lines[i];
    // Single-line form: resources: { money: a, food: b, water: c } (or withStocks style objects)
    if (/resources:\s*\{[^}]*money[^}]*food[^}]*water[^}]*\}/.test(line) && !/wood/.test(line)) {
      lines[i] = line.replace(/water:\s*([^,}]+)(\s*\})/, (m, v, tail) => `water: ${v}, wood: 0${tail}`);
      changed++;
      continue;
    }
    // Multi-line form: a block starting `resources: {` (or `resources: {\n`) where
    // subsequent lines contain money: and food: and water: and then the closing `},`
    if (/^\s*resources:\s*\{\s*$/.test(line) && !/wood/.test(lines[i+1] ?? '')) {
      // scan forward to closing brace at same indent
      const indent = line.match(/^\s*/)[0];
      let j = i + 1;
      let sawMoney = false, sawFood = false, sawWater = false, waterLine = -1, closeLine = -1;
      for (; j < lines.length && j < i + 12; j++) {
        const l = lines[j];
        if (/money:/.test(l)) sawMoney = true;
        if (/food:/.test(l)) sawFood = true;
        if (/^\s*water:/.test(l)) { sawWater = true; waterLine = j; }
        if (l.trim() === '},' || l.trim() === '}') { closeLine = j; break; }
      }
      if (sawMoney && sawFood && sawWater && waterLine >= 0 && closeLine === waterLine + 1) {
        const wl = lines[waterLine];
        const needsComma = !/,\s*$/.test(wl);
        lines[waterLine] = wl.replace(/\s*$/, m => m) + (needsComma ? ',' : '') ;
        // insert wood line after water line with same indent
        const wIndent = wl.match(/^\s*/)[0];
        lines.splice(waterLine + 1, 0, `${wIndent}wood: 0,`);
        changed++;
        i = waterLine + 1;
      }
    }
  }
  return { src: lines.join('\n'), changed };
}

let total = 0;
for (const f of files) {
  const src = fs.readFileSync(f, 'utf8');
  const { src: next, changed } = fixResourceBlocks(src);
  if (changed > 0) { fs.writeFileSync(f, next); total += changed; }
}
console.log('resource blocks fixed:', total);

// 2. Full SimulationState literals missing woodDeposits: files that build state
//    literals with `counters:` — add `woodDeposits: {},` right before counters
//    or after roads. Detect `roads: {},` (or roads: ...) followed by counters.
const stateFiles = ['tests/determinism.test.ts','tests/growthDemandMeasurement.test.ts','tests/scalePressureMeasurement.test.ts',
 'tests/spatialEquivalenceMeasurement.test.ts','tests/townGameplayQualityAudit.test.ts','tests/state.test.ts'];
let stateFixed = 0;
for (const f of stateFiles) {
  let src = fs.readFileSync(f, 'utf8');
  const before = src;
  // insert woodDeposits: {}, after a `roads: {...},` line IF the object also has counters and no woodDeposits
  const lines = src.split('\n');
  for (let i = 0; i < lines.length; i++) {
    if (/^\s*roads:\s*\{/.test(lines[i]) && !/woodDeposits/.test(src)) {
      // find end of this roads entry (line ending with }, or matching braces)
      let j = i, depth = 0, done = false;
      for (; j < Math.min(lines.length, i + 12); j++) {
        for (const ch of lines[j]) { if (ch === '{') depth++; if (ch === '}') depth--; }
        if (depth <= 0 && j > i) { done = true; break; }
      }
      if (done) {
        const indent = lines[i].match(/^\s*/)[0];
        lines.splice(j + 1, 0, `${indent}woodDeposits: {},`);
        stateFixed++;
        i = j + 1;
      }
    }
  }
  src = lines.join('\n');
  if (src !== before) fs.writeFileSync(f, src);
}
console.log('state literals fixed:', stateFixed);

