const blocks = txt.split('\n').reduce((acc, line) => {
  if (line.startsWith(' FAIL ')) acc.push({ name: line.slice(7).trim(), errs: [] });
  else if (acc.length && /AssertionError|expected .* to (be|equal|have|match|contain)|length of/.test(line) && acc[acc.length-1].errs.length < 2) {
    acc[acc.length-1].errs.push(line.trim().slice(0, 130));
  }
  return acc;
}, []);
for (const b of blocks) console.log(`• ${b.name}\n    ${b.errs.join('\n    ')}\n`);

