const fs = require('fs');
const { execSync } = require('child_process');

// A. ResourceStock literals: money/food/water/wood without stone -> add stone: 0
const stockFiles = execSync('grep -rl "Property" /dev/null 2>/dev/null; grep -rlE "wood: [^,}]+" tests/ --include=*.ts', {encoding:'utf8'}).trim().split('\n');
let stockFixed = 0;
for (const f of stockFiles) {
  let s = fs.readFileSync(f, 'utf8');
  const before = s;
  // single-line: { money: X, food: Y, water: Z, wood: W } without stone
  s = s.replace(/\{ money: ([^,}]+), food: ([^,}]+), water: ([^,}]+), wood: ([^,}]+) \}/g,
    (m, a, b, c, d) => `{ money: ${a}, food: ${b}, water: ${c}, wood: ${d}, stone: 0 }`);
  // multi-line: wood: X, (inside a block with money above) and no stone nearby
  const lines = s.split('\n');
  for (let i = 0; i < lines.length; i++) {
    if (/^\s*wood:\s*[^,]+,?\s*$/.test(lines[i])) {
      const back = lines.slice(Math.max(0, i - 8), i).join('\n');
      const fwd = lines.slice(i + 1, i + 3).join('\n');
      if (/money:/.test(back) && !/stone/.test(back + fwd) && /^\s*\]/.test(fwd)) {
        const indent = lines[i].match(/^\s*/)[0];
        const needsComma = !/,\s*$/.test(lines[i]);
        lines[i] = lines[i] + (needsComma ? ',' : '');
        lines.splice(i + 1, 0, `${indent}stone: 0,`);
        stockFixed++; i++;
      }
    }
  }
  s = lines.join('\n');
  if (s !== before) fs.writeFileSync(f, s);
}
console.log('stock files fixed:', stockFixed);

