  }
  state = { ...state, roads }
  types.forEach((type, index) => { state = op(state, type, 1 + index * 2, 2) })
  for (let index = 0; index < workers; index += 1) state = createColonist(state, `building-${index + 1}`).state
  return assignJobs(state)
}

